create or replace function public.epoch_auto_assign_team() returns trigger language plpgsql security definer set search_path=public as $$ declare n int; target int; existing int; team uuid; begin perform pg_advisory_xact_lock(hashtextextended(new.epoch_game_id::text,0)); select count(*) into n from epoch_players where epoch_game_id=new.epoch_game_id; target:=greatest(1,ceil(n::numeric/4)::int); select count(*) into existing from epoch_teams where epoch_game_id=new.epoch_game_id; if existing<target then insert into epoch_teams(epoch_game_id,team_name,team_number) select new.epoch_game_id,'TEAM '||i,i from generate_series(existing+1,target)i; end if; select t.epoch_team_id into team from epoch_teams t left join epoch_players p on p.epoch_team_id=t.epoch_team_id where t.epoch_game_id=new.epoch_game_id group by t.epoch_team_id order by count(p.epoch_player_id),random() limit 1; update epoch_players set epoch_team_id=team where epoch_player_id=new.epoch_player_id; return new; end; $$;
create trigger epoch_auto_assign_team_trigger after insert on public.epoch_players for each row execute function public.epoch_auto_assign_team();

